import unittest
from candidate import fib4

class TestFib4(unittest.TestCase):
    def test_fib4_normalcase(self):
        self.assertEqual(fib4(5), 4)

    def test_fib4_boundary_0(self):
        self.assertEqual(fib4(0), 0)

    def test_fib4_boundary_1(self):
        self.assertEqual(fib4(1), 0)

    def test_fib4_boundary_2(self):
        self.assertEqual(fib4(2), 2)

    def test_fib4_boundary_3(self):
        self.assertEqual(fib4(3), 0)

    def test_fib4_edgecase_negative(self):
        self.assertEqual(fib4(-1), None)

    def test_fib4_empty_input(self):
        self.assertRaises(TypeError, fib4, "")

    def test_fib4_non_integer(self):
        self.assertRaises(TypeError, fib4, 2.5)

    def test_fib4_long_input(self):
        self.assertRaises(ValueError, fib4, 999)

    def test_fib4_large_input(self):
        self.assertEqual(fib4(100), 354224848179261915075)

if __name__ == '__main__':
    unittest.main()
